import { type ReactNode, useEffect, useState } from "react";

type FederativeEntity = {
  id: string; name: string; kind: string; region: string; maturity: number; contracts: number;
  quality: number; sla: number; adoption: number; status: "Integrado" | "Parcial" | "Em adesão" | "Atenção";
  authority: string; lastSync: string; center: [number, number];
};
type DataContract = {
  id: string; title: string; custodian: string; consumer: string; schema: string; sla: string;
  classification: string; version: string; quality: number; deliveries: number;
  status: "Ativo" | "Homologação" | "Revisão" | "Suspenso"; lastDelivery: string;
};
type CatalogAsset = {
  id: string; name: string; domain: string; owner: string; standard: string; cadence: string;
  classification: string; lineage: string; consumers: string; quality: number;
  status: "Publicado" | "Homologação" | "Restrito";
};
type QualityFinding = {
  id: string; contractId: string; title: string; dimension: string; records: number;
  severity: "Crítica" | "Alta" | "Média" | "Baixa"; owner: string; due: string;
  status: "Aberto" | "Em tratamento" | "Validação" | "Resolvido";
};
type AccessGrant = {
  id: string; subject: string; purpose: string; scope: string; classification: string;
  legalBasis: string; expires: string; risk: "Alto" | "Médio" | "Baixo";
  status: "Solicitado" | "Revisão humana" | "Ativo" | "Revogado";
};
type InteropFlow = {
  id: string; source: string; target: string; standard: string; objects: string; latency: string;
  success: number; version: string; mapping: string; status: "Operacional" | "Parcial" | "Falha" | "Homologação";
};
type TransparencyPackage = {
  id: string; title: string; scope: string; classification: string; updated: string;
  completeness: number; owner: string; status: "Rascunho" | "Revisão" | "Aprovado interno" | "Publicado";
};
type AuditEntry = {
  id: string; time: string; actor: string; action: string; object: string; decision: string;
  correlation: string; hash: string; risk: "Alto" | "Médio" | "Baixo";
};
type GovernanceHubProps = {
  contextItem: string; territory: string; clockLabel: string; onNavigate: (item: string) => void;
  onOpenModule: (moduleId: string) => void; onToast: (message: string) => void;
};

